def design(feats) -> Design:
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids); types = list(feats.types)
    empty = Design(drivers=(), columns=(), products=(), loadings={})
    if p == 0 or n < 10 or np.unique(y).size < 2 or MAX_DRIVERS < 1: return empty
    labs = list(dict.fromkeys(feats.stratum))
    S = np.column_stack([np.ones(n)] + [np.asarray([s == l for s in feats.stratum], float) for l in labs[1:]])
    R = np.nan_to_num(np.corrcoef(X, rowvar=False)); A = np.abs(R)
    def ll(cols):
        Z = np.column_stack([S] + list(cols)) if len(cols) else S
        b = np.zeros(Z.shape[1])
        for _ in range(30):
            m = 1 / (1 + np.exp(-np.clip(Z @ b, -30, 30))); w = np.maximum(m * (1 - m), 1e-9)
            H = Z.T @ (Z * w[:, None]) + 1e-6 * np.eye(Z.shape[1])
            step = np.linalg.solve(H, Z.T @ (y - m)); b += step
            if np.max(np.abs(step)) < 1e-7: break
        m = np.clip(1 / (1 + np.exp(-np.clip(Z @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(m) + (1 - y) * np.log(1 - m)))
    col = lambda j: X[:, j[0]] * X[:, j[1]] if isinstance(j, tuple) else X[:, j]
    deg = (A >= 0.6).sum(0) - 1
    hubs = [int(j) for j in np.argsort(-deg, kind='stable') if types[j] == 'clinical' and deg[j] >= 3][:3]
    def gain(sel, j):
        base = [col(k) for k in sel] + [X[:, h] for h in hubs if h != j and h not in sel and A[h, j] < 0.95]
        return max(0., 2 * (ll(base + [X[:, j]]) - ll(base)))
    sel = []; gates = [0.5 / p, 0.1 / p, 0.05 / p]
    while len(sel) < MAX_DRIVERS:
        cand = [j for j in range(p) if all(A[j, k] < 0.6 for k in sel)]
        if not cand: break
        g = np.array([gain(sel, j) for j in cand]); j = cand[int(np.argmax(g))]
        if stats.chi2.sf(g.max(), 1) > gates[min(len(sel), 2)]: break
        cl = [k for k in cand if A[j, k] >= 0.6]
        if cl:
            L = {k: ll([col(q) for q in sel] + [X[:, k]]) for k in cl}
            cl = [k for k in cl if max(L.values()) - L[k] < (3. if k in hubs else 2.)]
            if any(k in hubs for k in cl): j = [k for k in cl if k in hubs][0]
            elif len(cl) > 1: j = max(cl, key=lambda k: float(np.sum(R[k, cl] ** 2)))
            elif cl: j = cl[0]
        sel.append(j)
    changed = True
    while changed and sel:
        changed = False
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if stats.chi2.sf(2 * (ll([col(k) for k in sel]) - ll([col(k) for k in rest])), 1) > 0.08 / p:
                sel.remove(j); changed = True; break
    pairs = [(a, b) for a in range(p) for b in range(a, p)]
    P = np.column_stack([X[:, a] * X[:, b] for a, b in pairs]); m0 = np.full(n, y.mean())
    sc = ((P.T @ (y - m0)) ** 2) / (np.var(P, 0) * n * y.mean() * (1 - y.mean()) + 1e-9)
    prods = []; thr = 0.005 / len(pairs)
    for i in np.argsort(-sc)[:15]:
        a, b = pairs[i]
        base = [col(k) for k in sel] + [X[:, k] for k in {a, b} if k not in sel]
        if stats.chi2.sf(2 * (ll(base + [P[:, i]]) - ll(base)), 1) < thr and all(len({a, b} & set(q)) == 0 for q in prods):
            prods.append((a, b))
        if len(prods) >= 2: break
    for a, b in prods:
        for k in (a, b):
            if k not in sel and len(sel) < MAX_DRIVERS: sel.append(k)
    loadings = {}
    for h in hubs:
        if h in sel or len(sel) >= MAX_DRIVERS: continue
        C = [m for m in range(p) if (m == h or A[h, m] >= 0.75) and all(A[m, k] < 0.9 for k in sel)]
        if h not in C: continue
        w = np.array([1. if m == h else np.sign(R[h, m]) for m in C])
        sco = (X[:, C] * w).sum(1); sco = (sco - sco.mean()) / max(sco.std(), 1e-8)
        base = [col(k) for k in sel]
        gs = max(0., 2 * (ll(base + [sco]) - ll(base)))
        if stats.chi2.sf(gs, 1) < (0.05 if sel else 0.01):
            gm = {m: max(0., 2 * (ll(base + [X[:, m]]) - ll(base))) for m in C}
            best = max(gm, key=gm.get)
            sel.append(best if gm[best] > gm[h] + 6 else h)
            loadings = {ids[m]: float(w[i]) for i, m in enumerate(C)}
    drivers = tuple(ids[j] for j in sel[:MAX_DRIVERS])
    if not drivers: return empty
    cols = list(sel) + [h for h in hubs if h not in sel and all(A[h, k] < 0.95 for k in sel)]
    return Design(drivers=drivers, columns=tuple(ids[j] for j in cols),
                  products=tuple((ids[a], ids[b]) for a, b in prods), loadings=loadings)

